const items = $input.all();
const results = [];

for (const item of items) {
  const message = item.json.message;
  const chat_id = String(message.chat.id);
  let user_message = '';
  let message_type = 'text';

  if (message.voice || message.audio) {
    message_type = 'audio';
    user_message = '';
  } else if (message.photo) {
    message_type = 'photo';
    user_message = message.caption || 'Image envoyée sans légende. Que souhaites-tu en faire?';
  } else if (message.text) {
    message_type = 'text';
    user_message = message.text;
  } else {
    user_message = 'Message non reconnu.';
  }

  const result = {
    json: { user_message, chat_id, message_type }
  };

  // Conserver les données binaires (audio Telegram)
  if (item.binary && Object.keys(item.binary).length > 0) {
    result.binary = item.binary;
  }

  results.push(result);
}

return results;

const items = $input.all();
const processInput = $('Process Input').first().json;
const results = [];

for (const item of items) {
  const transcription = item.json.text || item.json.transcription || JSON.stringify(item.json);
  results.push({
    json: {
      user_message: transcription,
      chat_id: processInput.chat_id,
      message_type: 'audio'
    }
  });
}

return results;

